const templates = Draft.query('', 'all', ['template']);
if (templates.length === 0) { context.fail('No drafts have the template tag.'); }
else {
  const choice = SelectPrompt.create(); choice.title = 'Choose a template';
  templates.forEach(item => choice.addItem(item.uuid, item.displayTitle));
  if (!choice.show()) { context.cancel(); }
  else {
    const source = Draft.find(choice.selectedItem.id);
    const result = Draft.create();
    result.content = source.processTemplate(source.content);
    result.tags = source.tags.filter(tag => tag.toLowerCase() !== 'template');
    result.update(); editor.load(result);
  }
}
